class Pet:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def introduce(self):
        return f"I am {self.name} and I am {self.age} years old."


rex = Pet("Rex", 3)
misty = Pet("Misty", 5)
print(rex.introduce())
print(misty.introduce())
